// Parse chat input and classify intent
const input = $input.first().json;
const message = (input.message || input.text || '').toLowerCase();

let intent = 'GENERAL_CHAT';
const docKeywords = ['create document', 'write requirements', 'system design', 'generate doc', 'draft document', 'create srs', 'create sdd', 'requirements doc', 'design doc', 'document for', 'spec for'];
const ragKeywords = ['what is', 'how does', 'explain', 'tell me about', 'what are', 'describe', 'api for', 'endpoint for', 'architecture of', 'how do'];

if (docKeywords.some(kw => message.includes(kw))) {
  intent = 'CREATE_DOCUMENT';
} else if (ragKeywords.some(kw => message.startsWith(kw)) || message.endsWith('?')) {
  intent = 'RAG_QUERY';
}

return [{
  json: {
    sessionId: input.sessionId || input.metadata?.sessionId || 'session_' + Date.now(),
    userMessage: input.message || input.text || '',
    intent: intent,
    attachments: input.attachments || input.files || [],
    chatInput: input,
    timestamp: new Date().toISOString()
  }
}];

// Assemble context for routing
const session = $input.first().json;
const input = $input.first().json;

return [{
  json: {
    sessionId: input.sessionId,
    userMessage: input.userMessage,
    intent: input.intent,
    attachments: input.attachments,
    timestamp: input.timestamp
  }
}];

// Format final response for chat
const result = $input.first().json;

let responseText = result.response || result.output || result.text || result.content || '';
if (typeof responseText === 'object') {
  responseText = responseText.text || responseText.content || responseText.message || JSON.stringify(responseText);
}

let footer = '';
if (result.documentId) {
  footer = `\n\n---\n📄 **Document draft created**: ${result.title || 'Untitled'}\n🆔 Draft ID: ${result.documentId}\n⏳ Awaiting your review...`;
}

return [{
  json: {
    response: responseText + footer,
    sessionId: result.sessionId,
    intent: result.intent
  }
}];
